40	const FACTUALITY_CATEGORY_DESCRIPTIONS: Record<string, string> = {
41	  A: 'The submitted answer is a subset of the expert answer and is fully consistent with it.',
42	  B: 'The submitted answer is a superset of the expert answer and is fully consistent with it.',
43	  C: 'The submitted answer contains all the same details as the expert answer.',
44	  D: 'There is a disagreement between the submitted answer and the expert answer.',
45	  E: "The answers differ, but these differences don't matter from the perspective of factuality.",
46	};
