3	/**
4	 * Normalize token usage for matcher results. Unlike the evaluator-level
5	 * normalizeTokenUsage, this excludes the `assertions` field and preserves
6	 * the existing completionDetails shape (passing through whatever the
7	 * provider returned, or undefined if not present).
8	 */
9	export function normalizeMatcherTokenUsage(
10	  tokenUsage: Partial<TokenUsage> | undefined,
11	): TokenUsage {
12	  return {
13	    total: tokenUsage?.total || 0,
14	    prompt: tokenUsage?.prompt || 0,
15	    completion: tokenUsage?.completion || 0,
16	    cached: tokenUsage?.cached || 0,
17	    numRequests: tokenUsage?.numRequests || 0,
18	    completionDetails: tokenUsage?.completionDetails || {
19	      reasoning: 0,
20	      acceptedPrediction: 0,
21	      rejectedPrediction: 0,
22	    },
23	  };
24	}
