}", "newString": "/**
 * Build a grader failure result. A grader transport/parse failure is not
 * evidence that the criterion was or was not met, so we tag it with
 * `metadata.graderError` (see `isGraderFailure`). Callers that support inverse
 * semantics (e.g. `not-llm-rubric`, `not-trajectory:goal-success`) must
 * propagate such results verbatim without flipping pass/score.
 */
function graderFail(
  reason: string,
  tokenUsage?: ProviderResponse['tokenUsage'],
): Omit<GradingResult, 'assertion'> {
  return {
    ...fail(reason, tokenUsage),
    metadata: { graderError: true },
  };
}

function parseJsonGradingResponse(
  label: string,
  resp: ProviderResponse,
): { parsed?: Partial<GradingResult>; failure?: Omit<GradingResult, 'assertion'> } {
  let jsonObjects: unknown[] = [];
  if (typeof resp.output === 'string') {
    try {
      jsonObjects = extractJsonObjects(resp.output);
      if (jsonObjects.length === 0) {
        return {
          failure: graderFail(`Could not extract JSON from ${label} response`, resp.tokenUsage),
        };
      }
    } catch (err) {
      return {
        failure: graderFail(
          `${label} produced malformed response: ${err}\n\n${resp.output}`,
          resp.tokenUsage,
        ),
